(173, 'xe-mitsubishi-quang-nam-002.png', '', '', 'Luôn cam kết mang lại mức giá ưu đãi nhất cho quý khách với thời gian giao xe nhanh nhất.', 'GIÁ ƯU ĐÃI – GIAO XE SỚM', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(176, 'oto-mitsubishi-quang-nam-001.png', '', '', 'Chúng tôi luôn cập nhật sớm nhất các chương trình khuyến mãi của hãng và đại lý nhằm mang đến lợi ích cao nhất cho khách hàng.', 'KHUYẾN MÃI TỐT NHẤT', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(177, 'oto-mitsubishi-quang-nam-0043.png', '', '', 'Chúng tôi cam kết mang đến dịch vụ bảo dưỡng và sửa chữa theo tiêu chuẩn chất lượng của Mitsubishi trên toàn cầu.', 'DỊCH VỤ HẬU MÃI CHU ĐÁO', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(178, 'oto-mitsubishi-quang-nam-004.png', '', '', 'Hỗ trợ quý khách dễ dàng trải nghiệm xe Mitsubishi mà không tốn thời gian.', 'LÁI THỬ TẬN NHÀ', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'https://www.mitsubishimotorsquangnam.com.vn/');

