(6, 'co lenen<br />\r\n<div id=\"eJOY__extension_root\" style=\"all: unset;\">&nbsp;</div>', '<p class=\"MsoNoSpacing\"><span style=\"color: rgb(255, 204, 0);\"><span style=\"font-size: large;\"><strong>Tại sao lại chọn ch&uacute;ng t&ocirc;i?</strong></span></span><o:p></o:p></p>\r\n<p class=\"MsoNoSpacing\"><strong><span style=\"font-size: larger;\">Được thu mua với gi&aacute; cao, s&aacute;t thị trường</span></strong><o:p></o:p></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size: larger;\">Gi&aacute; thu mua phế liệu l&agrave; một trong những vấn đề được quan t&acirc;m nhiều nhất. Tuy nhi&ecirc;n với <strong>Tiến Ph&aacute;t</strong>, ch&uacute;ng t&ocirc;i cam kết sẽ l&agrave; c&ocirc;ng ty đưa ra cho qu&yacute; kh&aacute;ch h&agrave;ng mức gi&aacute; cao v&agrave; s&aacute;t với thị trường nhất, đảm bảo sẽ cao nhất to&agrave;n quốc hiện nay.</span><o:p></o:p></p>\r\n<p class=\"MsoNoSpacing\"><strong><span style=\"font-size: larger;\">Dịch vụ chuy&ecirc;n nghiệp</span></strong><o:p></o:p></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size: larger;\">Khi ho&agrave;n tất thủ tục thu mua phế liệu với <strong>Tiến Ph&aacute;t,</strong> ch&uacute;ng t&ocirc;i sẽ mang lại cho bạn dịch vụ chăm s&oacute;c kh&aacute;ch h&agrave;ng tốt nhất, k&egrave;m theo đ&oacute; l&agrave; đội ngũ nh&acirc;n vi&ecirc;n chuy&ecirc;n nghiệp, th&acirc;n thiện v&agrave; nhiệt t&igrave;nh nhất.</span><o:p></o:p></p>\r\n<p class=\"MsoNoSpacing\"><strong><span style=\"font-size: larger;\">Thanh to&aacute;n nhanh ch&oacute;ng</span></strong><o:p></o:p></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size: large;\"><strong>Tiến Ph&aacute;t</strong></span><span style=\"font-size: larger;\"> cam kết sẽ thanh to&aacute;n nhanh ch&oacute;ng nhất cho kh&aacute;ch h&agrave;ng khi thu mua phế liệu. Ch&uacute;ng t&ocirc;i c&oacute; hai h&igrave;nh thức thanh to&aacute;n ch&iacute;nh l&agrave; tiền mặt hoặc chuyển khoản. Qu&yacute; kh&aacute;ch c&oacute; thể lựa chọn bất cứ loại h&igrave;nh n&agrave;o m&agrave; qu&yacute; kh&aacute;ch cho rằng đ&oacute; l&agrave; ph&ugrave; hợp nhất.</span><o:p></o:p></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"color: rgb(0, 0, 0);\"><em><strong><span style=\"font-size: larger;\">Cam kết thu mua với gi&aacute; cao hơn thị trường tới 30% !</span></strong></em></span><o:p></o:p></p>');
