INSERT INTO `du_lieu_1_tin` (`id`, `noidung_en`, `noidung`) VALUES
(17, 'h&igrave;nh thức thanh to&aacute;n', '<div style=\"text-align: left;\">\r\n<p class=\"MsoNoSpacing\">&nbsp;</p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Nhu cầu thu mua phế liệu, đồ cũ c&ocirc;ng nghiệp của Tiến</span></b><span style=\"font-size:13.0pt;&#10;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> <b style=\"mso-bidi-font-weight:normal\">Ph&aacute;t</b> <span style=\"mso-spacerun:yes\">&nbsp;</span>rất được mọi người lựa chọn, c&aacute;c bạn đang tốn rất nhiều thời gian để t&igrave;m một đơn vị thu mua phế liệu gi&aacute; cao chất lượng, <b style=\"mso-bidi-font-weight:normal\">Đồ cũ Tiến Ph&aacute;t</b> ph&ugrave; hợp với gi&aacute; cả của mỗi C&ocirc;ng ty, chắc hẳn c&aacute;c bạn cũng đ&atilde; gh&eacute; qua rất nh&igrave;u cửa h&agrave;ng để tham khảo về gi&aacute; cả v&agrave; Cơ sở thu mua c&ograve;n chần chừ g&igrave; nữa m&agrave; kh&ocirc;ng li&ecirc;n hệ <b style=\"mso-bidi-font-weight:normal\"><span style=\"color:red\">Hotline:</span></b><span style=\"color:red\"> </span><b style=\"mso-bidi-font-weight:normal\"><i style=\"mso-bidi-font-style:normal\">0962 307 123</i></b><o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Thu mua đồ cũ Tiến Ph&aacute;t Cam kết:<o:p></o:p></span></b></p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Thu mua phế liệu tận nơi:</span></b><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> Lu&ocirc;n cập nhật gi&aacute; thị trường li&ecirc;n tục, b&aacute;o gi&aacute; chuẩn x&aacute;c v&agrave; c&oacute; đội ngũ bốc v&aacute;c thu mua chuy&ecirc;n nghiệp, an to&agrave;n.<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"mso-spacerun:yes\">&nbsp;</span><b style=\"mso-bidi-font-weight:normal\">Hệ thống cơ sở thu mua phế liệu:</b> hệ thống cơ sở d&agrave;y đặc từ BẮC V&Agrave;O NAM , c&oacute; xe vận chuyển tận nơi, nhanh gọn, sạch sẻ, uy t&iacute;n. Kh&ocirc;ng ảnh hưởng đến m&ocirc;i trường xung quanh, g&oacute;p phần chung tay bảo vệ mội trường.<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"mso-spacerun:yes\">&nbsp;</span><b style=\"mso-bidi-font-weight:normal\">Thu mua phế liệu gi&aacute; cao tại miền nam</b> cam kết lu&ocirc;n mua với gi&aacute; cao nhất trong khu vực, c&oacute; bồi dưỡng hoa hồng cho người giới thiệu.<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:red\">Quy tr&igrave;nh mua b&aacute;n phế liệu đồ cũ Tiến Ph&aacute;t</span></b><span style=\"font-size:13.0pt;&#10;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:red\"> </span><span style=\"font-size:&#10;13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">v&ocirc; c&ugrave;ng chuy&ecirc;n nghiệp v&agrave; nhanh ch&oacute;ng, đơn giản ho&aacute; giấy tờ, thủ tục nhất c&oacute; thể nhằm tiết kiệm thời gian tối đa cho kh&aacute;ch h&agrave;ng.<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Cụ thể qu&aacute; tr&igrave;nh mua b&aacute;n tại <span style=\"color:red\">Tiến Ph&aacute;t </span>sẽ được thực hiện th&ocirc;ng qua 5 bước như sau:<o:p></o:p></span></b></p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><i style=\"mso-bidi-font-style:normal\"><span style=\"font-size:13.0pt;font-family:&#10;&quot;Arial&quot;,&quot;sans-serif&quot;\">Bước 1:</span></i></b><span style=\"font-size:13.0pt;&#10;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> Tiếp nhận th&ocirc;ng tin, khảo s&aacute;t nhanh phế liệu cần b&aacute;n v&agrave; b&aacute;o gi&aacute;<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Sau khi nhận được th&ocirc;ng tin cần b&aacute;n phế liệu từ kh&aacute;ch h&agrave;ng, ch&uacute;ng t&ocirc;i sẽ cử một đội ngũ nh&acirc;n vi&ecirc;n đến tận nơi để khảo s&aacute;t trong thời gian sớm nhất, th&ocirc;ng thường l&agrave; từ 15-30 ph&uacute;t. Sau khi khảo s&aacute;t xong, ch&uacute;ng t&ocirc;i sẽ tiến h&agrave;nh b&aacute;o gi&aacute; v&agrave; thoả thuận gi&aacute; cả với kh&aacute;ch h&agrave;ng. V&agrave; cuối c&ugrave;ng l&agrave; chốt gi&aacute; v&agrave; hẹn thời gian thu gom phế liệu.<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><i style=\"mso-bidi-font-style:normal\"><span style=\"font-size:13.0pt;font-family:&#10;&quot;Arial&quot;,&quot;sans-serif&quot;\">Bước 2:</span></i></b><span style=\"font-size:13.0pt;&#10;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> K&yacute; kết hợp đồng thu mua<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Sau khi đạt được thoả thuận giữa 2 b&ecirc;n, ch&uacute;ng t&ocirc;i sẽ tiến h&agrave;nh lập hợp đồng c&oacute; đ&oacute;ng dấu mộc của c&ocirc;ng ty. Trong hợp đồng sẽ ghi r&otilde; mọi điều khoản như thời gian xuống lấy h&agrave;ng cũng như h&igrave;nh thức thanh to&aacute;n v&agrave; ho&aacute; đơn. Sau đ&oacute; hai b&ecirc;n tiến h&agrave;nh k&yacute; kết v&agrave; thực hiện đ&uacute;ng như trong hợp đồng.<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><i style=\"mso-bidi-font-style:normal\"><span style=\"font-size:13.0pt;font-family:&#10;&quot;Arial&quot;,&quot;sans-serif&quot;\">Bước 3:</span></i></b><span style=\"font-size:13.0pt;&#10;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> Thu gom, vận chuyển phế liệu<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Sau khi ho&agrave;n th&agrave;nh k&yacute; kết hợp đồng, theo đ&uacute;ng thời gian đ&atilde; thoả thuận ch&uacute;ng t&ocirc;i sẽ cho đội ngũ nh&acirc;n c&ocirc;ng, xe vận chuyển chuy&ecirc;n dụng ph&ugrave; hợp với loại phế liệu cần thu gom đến tận nơi để tiến h&agrave;nh vận chuyển về kho b&atilde;i.<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><i style=\"mso-bidi-font-style:normal\"><span style=\"font-size:13.0pt;font-family:&#10;&quot;Arial&quot;,&quot;sans-serif&quot;\">Bước 4:</span></i></b><span style=\"font-size:13.0pt;&#10;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> Dọn dẹp sạch sẽ, thanh to&aacute;n đủ tiền phế liệu như đ&atilde; thoả thuận<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Sau khi thu gom đủ khối lượng phế liệu đ&atilde; thoả thuận l&ecirc;n xe vận chuyển, trước khi rời đi nh&acirc;n vi&ecirc;n ch&uacute;ng t&ocirc;i sẽ dọn dẹp sạch sẽ trả lại kh&ocirc;ng gian gọn g&agrave;ng cho kh&aacute;ch h&agrave;ng. Đồng thời thanh to&aacute;n đầy đủ tiền phế liệu cho kh&aacute;ch h&agrave;ng dưới h&igrave;nh thức tiền mặt hoặc chuyển khoản như đ&atilde; liệt k&ecirc; r&otilde; trong hợp đồng.<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><b style=\"mso-bidi-font-weight:normal\"><i style=\"mso-bidi-font-style:normal\"><span style=\"font-size:13.0pt;font-family:&#10;&quot;Arial&quot;,&quot;sans-serif&quot;\">Bước 5:</span></i></b><span style=\"font-size:13.0pt;&#10;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> Chăm s&oacute;c kh&aacute;ch h&agrave;ng <o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Sau khi thu mua tại <b style=\"mso-bidi-font-weight:normal\"><span style=\"color:red\">Tiến Ph&aacute;t</span></b><span style=\"color:red\"> </span>lần đầu ti&ecirc;n, th&ocirc;ng tin qu&yacute; kh&aacute;ch sẽ được chuyển cho bộ phận CSKH để được hỗ trợ tư vấn, giải đ&aacute;p miễn ph&iacute; về qu&aacute; tr&igrave;nh thực hiện c&ocirc;ng việc thu mua của nh&acirc;n vi&ecirc;n. Đặc biệt từ lần mua b&aacute;n thứ 2 trở đi, kh&aacute;ch h&agrave;ng sẽ được &aacute;p dụng ch&iacute;nh s&aacute;ch trợ gi&aacute; v&agrave; nhiều ưu đ&atilde;i kh&aacute;c.<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><strong><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">C&Ocirc;NG TY TNHH DỊCH VỤ THU MUA ĐỒ CŨ TIẾN PH&Aacute;T</span></strong><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><strong><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Hotline:</span></strong><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> 0962 307 123<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><strong><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Gmail:</span></strong><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> dienlanhtienphat@gmail.com<o:p></o:p></span></p>\r\n<p class=\"MsoNoSpacing\"><strong><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">Website:</span></strong><span style=\"font-size:13.0pt;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"> thumuadocutienphat.com.vn<o:p></o:p></span></p>\r\n<p>&nbsp;</p>\r\n</div>'),
(18, 'h&agrave;ng nhập khẩu', '<font size=\"3\">h&agrave;ng nhập khẩu</font>'),
(19, 'h&agrave;ng trong kho', '<iframe width=\"410\" height=\"300\" src=\"https://www.youtube.com/embed/TKutRsBM_1k\" frameborder=\"0\" allowfullscreen></iframe>'),
(20, 'th&ocirc;ng tin li&ecirc;n quan', '<div style=\"text-align: justify;\"><span style=\"font-size: x-large;\"><span style=\"color: rgb(255, 0, 0);\"><strong>C&Ocirc;NG TY THU MUA PHẾ LIỆU GI&Aacute; CAO TIẾN PH&Aacute;T</strong></span></span><span style=\"font-size: larger;\"><br />\r\n<span style=\"font-size: large;\"><strong>Tiến Ph&aacute;t&nbsp;</strong></span><strong>&nbsp;</strong>l&agrave; c&ocirc;ng ty thu mua phế liệu gi&aacute; cao c&aacute;c loại như sắt vụn, đồng, nh&ocirc;m, hợp kim, thiếc, inox, nhựa, vải, giấy, bao b&igrave;, nilon của c&aacute;c nh&agrave; m&aacute;y, c&ocirc;ng ty, x&iacute; nghiệp, cửa h&agrave;ng,&hellip; với khối lượng đơn h&agrave;ng lớn tr&ecirc;n to&agrave;n quốc. Chỉ với một cuộc gọi, ch&uacute;ng t&ocirc;i sẽ cho đội xe chuy&ecirc;n dụng xuống l&agrave;m việc với qu&yacute; kh&aacute;ch h&agrave;ng ngay trong ng&agrave;y. Với hơn 12 năm trong nghề Tiến Ph&aacute;t tự tin sẽ l&agrave; đối t&aacute;c tin cậy số 1 của qu&yacute; kh&aacute;ch h&agrave;ng.<br />\r\nCam kết gi&aacute; thu mua phế liệu lu&ocirc;n cao hơn c&aacute;c đơn vị kh&aacute;c v&agrave; đặc biệt l&agrave; lu&ocirc;n tr&iacute;ch lợi nhuận, hoa hồng hấp dẫn cho người giới thiệu.<br />\r\n<span style=\"color: rgb(0, 0, 255);\"><span style=\"font-size: x-large;\"><strong>HOTLINE HỖ TRỢ 24/7 </strong></span></span><span style=\"color: rgb(255, 0, 0);\"><span style=\"font-size: x-large;\"><strong>: 0962 307 123 &ndash; A. Tiến</strong></span><br />\r\n</span><em><strong>XEM BẢNG GI&Aacute; PHẾ LIỆU 2024</strong></em><br />\r\nVới những lợi thế sau đ&acirc;y,<strong> Đồ Cũ Tiến Ph&aacute;t</strong>&nbsp; tự tin mang đến cho qu&yacute; kh&aacute;ch sự phục vụ tốt nhất :<br />\r\n<em><strong>Lợi thế về gi&aacute; : </strong></em>Ch&uacute;ng t&ocirc;i lu&ocirc;n cam kết v&agrave; bảo đảm gi&aacute; thua mua phế liệu lu&ocirc;n cao hơn 30% so với thị trường l&agrave; ho&agrave;n to&agrave;n sự thật.<br />\r\n<em><strong>Lợi thế về t&agrave;i ch&iacute;nh :</strong></em> Với hơn 10 năm kinh nghiệm trong nghề phế liệu,&nbsp;</span><span style=\"font-size: large;\"><strong>Tiến Ph&aacute;t</strong></span><span style=\"font-size: larger;\">&nbsp;lu&ocirc;n tự tin v&agrave;o khả năng v&agrave;o t&agrave;i ch&iacute;nh của m&igrave;nh. Ch&uacute;ng t&ocirc;i cam kết lu&ocirc;n đảm bảo việc thanh to&aacute;n một lần cho qu&yacute; kh&aacute;ch h&agrave;ng bằng tiền mặt hoặc chuyển khoản.<br />\r\n<em><strong>Lợi thế về kho b&atilde;i : </strong></em>Ở mỗi tỉnh th&agrave;nh phố tr&ecirc;n khắp cả nước. Ch&uacute;ng t&ocirc;i đều c&oacute; &iacute;t nhất 3 kho b&atilde;i chiến lược để c&oacute; thể đảm bảo việc thu mua phế liệu cho c&aacute;c c&ocirc;ng ty, doanh nghiệp, cơ sở sản xuất một c&aacute;ch nhanh ch&oacute;ng, thuận tiện nhất.<br />\r\n<em><strong>Lợi thế về nh&acirc;n lực :</strong></em> Hiện tại c&ocirc;ng ty ch&uacute;ng t&ocirc;i đang c&oacute; nhiều nh&acirc;n lực để đ&aacute;p ứng v&agrave; phục vụ c&ocirc;ng t&aacute;c th&aacute;o dỡ, bốc xếp, vận chuyển, dọn dẹp vệ sinh kho b&atilde;i chứa phế liệu cho qu&yacute; kh&aacute;ch h&agrave;ng tr&ecirc;n to&agrave;n quốc.<br />\r\n<em><strong>Lợi thế về phương tiện : </strong></em>Hiện c&ocirc;ng ty thu mua phế liệu&nbsp;</span><span style=\"font-size: large;\"><strong>Tiến Ph&aacute;t</strong>&nbsp;</span><span style=\"font-size: larger;\">c&oacute; c&aacute;c loại xe tải, xe cẩu, xe cạp, xe n&acirc;ng v&agrave; một số m&aacute;y m&oacute;c chuy&ecirc;n dụng d&ugrave;ng để vận chuyển c&aacute;c loại phế liệu.</span></div>'),
(21, 'từ kh&oacute;a', '<a href=\"http://atvmedia.net\"><u><span style=\"font-size: x-large;\"><span style=\"color: rgb(255, 0, 0);\">từ kh&oacute;a&nbsp; </span></span></u></a><a href=\"http://hangquocte.com\"><u><span style=\"font-size: x-large;\"><span style=\"color: rgb(255, 0, 0);\">nh&acirc;t an htthth hksaj;lfj jf;lsdjf;lsd</span></span></u><strong><span style=\"font-size: medium;\"><span style=\"color: rgb(255, 0, 0);\"><br />\r\n</span></span></strong></a>');

