INSERT INTO `loai_tin_sanpham` (`id`, `thuocloai`, `thuocloai_en`, `hinhanh`, `logo`, `noidung`, `noidung_en`) VALUES
(31, 'Thu Mua Nhà Xưởng', '', 'thanh-ly-dien-lanh-cu-binhduong-012.gif', 'thu-mua-may-lanh-quan-12.jpg', '<div style=\"text-align: justify;\"><span style=\"font-size: larger;\">Luật hiện h&agrave;nh quy định, nếu kh&ocirc;ng đồng &yacute; quyết định thu hồi đất, người d&acirc;n c&oacute; thể khiếu nại v&agrave; khiếu kiện l&ecirc;n UBND cấp huyện hoặc cấp tỉnh tối đa hai lần. Sau đ&oacute;, nếu họ vẫn kh&ocirc;ng đồng &yacute; th&igrave; sẽ khởi kiện ra to&agrave;. Tuy nhi&ecirc;n, thực tế nhiều vụ khiếu nại h&agrave;nh ch&iacute;nh qua UBND kh&ocirc;ng được giải quyết đ&uacute;ng thời hạn, dẫn đến thời gian giải quyết k&eacute;o d&agrave;i. Kh&ocirc;ng &iacute;t vụ UBND đ&atilde; ban h&agrave;nh quyết định giải quyết 1-2 lần, nhưng lại bị t&ograve;a &aacute;n tuy&ecirc;n huỷ.<br />\r\n<br />\r\nTheo luật sư Trung, việc xử ở to&agrave; &aacute;n sẽ tạo điều kiện để d&acirc;n đối thoại trực tiếp với người ra quyết định h&agrave;nh ch&iacute;nh. To&agrave; cũng c&oacute; luật ho&agrave; giải n&ecirc;n khi hai b&ecirc;n c&oacute; chung tiếng n&oacute;i c&oacute; thể r&uacute;t ngắn thời gian giải quyết. &Ocirc;ng dẫn chứng ở một số quốc gia như Anh, Ph&aacute;p, &Yacute;, Đức, Phần Lan, Th&aacute;i Lan c&aacute;c vụ khiếu nại đất đai đều do to&agrave; &aacute;n ph&acirc;n xử. &quot;Do đ&oacute;, bỏ khiếu nại qua UBND c&aacute;c cấp l&agrave; ph&ugrave; hợp với xu hướng ph&aacute;t triển quốc tế&quot;, &ocirc;ng n&oacute;i.<br />\r\n<br />\r\nĐồng quan điểm, PGS.TS Phan Trung Hiền, Trưởng khoa Luật Đại học Cần Thơ, n&oacute;i quy định hiện h&agrave;nh khiến người d&acirc;n trong v&ograve;ng luẩn quẩn v&igrave; UBND cấp tỉnh vừa l&agrave; chủ thể định gi&aacute; đất t&iacute;nh bồi thường, vừa giải quyết khiếu nại. &quot;Như vậy l&agrave; UBND vừa đ&aacute; b&oacute;ng, vừa thổi c&ograve;i, vừa cho thu&ecirc; s&acirc;n&quot;, &ocirc;ng Hiền n&oacute;i v&agrave; cho rằng giải quyết khiếu nại, khiếu kiện l&agrave; vai tr&ograve; của to&agrave; &aacute;n.<br />\r\n<br />\r\nTrong khi đ&oacute;, luật sư Nguyễn Văn Hậu cho rằng chuyển to&agrave;n bộ thẩm quyền giải quyết tranh chấp đất đai cho to&agrave; &aacute;n l&agrave; t&acirc;m l&yacute; &quot;l&agrave;m kh&ocirc;ng được th&igrave; đẩy qua to&agrave; cho xong&quot;. &Ocirc;ng dẫn chứng Nghị quyết 18/2022 của Trung ương về đất đai n&ecirc;u r&otilde; phương ch&acirc;m &quot;giải quyết triệt để tranh chấp về đất đai từ cơ sở, tr&aacute;nh vượt cấp l&ecirc;n Trung ương&quot;. Do đ&oacute;, dự thảo sửa theo hướng bỏ thẩm quyền của UBND l&agrave; thu hẹp bớt quyền của người d&acirc;n v&agrave; bỏ một cơ chế giải quyết linh hoạt.</span></div>', '&nbsp;7yy7');

